CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS app;
CREATE TABLE app.regions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, is_public boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.neighborhoods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), region_id uuid NOT NULL REFERENCES app.regions(id), name text NOT NULL, slug text NOT NULL, valid_from date NOT NULL, valid_to date, is_public boolean NOT NULL DEFAULT true, UNIQUE(region_id,name));
CREATE TABLE app.property_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, category text NOT NULL);
CREATE TABLE app.properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_code text NOT NULL UNIQUE, property_type_id uuid NOT NULL REFERENCES app.property_types(id), area_m2 numeric(12,2), building_area_m2 numeric(12,2), floor integer, build_year integer, status text NOT NULL DEFAULT 'active', private_address text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(area_m2 IS NULL OR area_m2>0), CHECK(building_area_m2 IS NULL OR building_area_m2>0));
CREATE TABLE app.data_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, source_type text NOT NULL, reference text, reliability text);
CREATE TABLE app.market_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid REFERENCES app.properties(id), record_month date NOT NULL, property_type_id uuid NOT NULL REFERENCES app.property_types(id), region_id uuid NOT NULL REFERENCES app.regions(id), neighborhood_id uuid REFERENCES app.neighborhoods(id), region_name_snapshot text NOT NULL, neighborhood_name_snapshot text, source_id uuid REFERENCES app.data_sources(id), status text NOT NULL DEFAULT 'raw', is_public boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), market_record_id uuid NOT NULL UNIQUE REFERENCES app.market_records(id), transaction_month date NOT NULL, final_price_toman bigint NOT NULL CHECK(final_price_toman>0), price_per_m2_toman bigint CHECK(price_per_m2_toman IS NULL OR price_per_m2_toman>0), verified_at timestamptz, is_public boolean NOT NULL DEFAULT false);
CREATE TABLE app.listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), market_record_id uuid NOT NULL UNIQUE REFERENCES app.market_records(id), asking_price_toman bigint NOT NULL CHECK(asking_price_toman>0), price_per_m2_toman bigint CHECK(price_per_m2_toman IS NULL OR price_per_m2_toman>0), published_at timestamptz, closed_at timestamptz, status text NOT NULL DEFAULT 'draft', is_public boolean NOT NULL DEFAULT false, CHECK(closed_at IS NULL OR published_at IS NULL OR closed_at>=published_at));
CREATE TABLE app.listing_price_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES app.listings(id), old_price_toman bigint CHECK(old_price_toman IS NULL OR old_price_toman>0), new_price_toman bigint NOT NULL CHECK(new_price_toman>0), changed_at timestamptz NOT NULL DEFAULT now(), changed_by uuid, reason text);
CREATE TABLE app.price_indices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_type_id uuid NOT NULL REFERENCES app.property_types(id), region_id uuid REFERENCES app.regions(id), period date NOT NULL, value numeric(14,4) NOT NULL, change_pct numeric(9,4), sample_count integer NOT NULL CHECK(sample_count>=0), confidence_level text NOT NULL, formula_version text NOT NULL, is_public boolean NOT NULL DEFAULT false, UNIQUE(property_type_id,region_id,period,formula_version));
CREATE TABLE app.liquidity_indices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), region_id uuid NOT NULL REFERENCES app.regions(id), period date NOT NULL, score numeric(8,4), median_days_on_market numeric(10,2), listing_to_transaction_rate numeric(8,4), inventory_turnover_rate numeric(8,4), sale_to_ask_ratio numeric(8,4), sample_count integer NOT NULL CHECK(sample_count>=0), confidence_level text NOT NULL, formula_version text NOT NULL, is_public boolean NOT NULL DEFAULT false, UNIQUE(region_id,period,formula_version));
CREATE TABLE app.users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','admin','data_entry','analyst','editor','viewer')), two_factor_enabled boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES app.users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.monthly_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period date NOT NULL UNIQUE, title text NOT NULL, body text, status text NOT NULL DEFAULT 'draft', published_at timestamptz);
CREATE TABLE app.special_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid REFERENCES app.properties(id), month date NOT NULL UNIQUE, reason text NOT NULL, status text NOT NULL DEFAULT 'draft', is_public boolean NOT NULL DEFAULT false);
CREATE TABLE app.social_content_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, content_type text NOT NULL, template text NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE app.social_content_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid REFERENCES app.social_content_templates(id), report_id uuid REFERENCES app.monthly_reports(id), storage_key text NOT NULL, mime_type text NOT NULL, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX market_records_period_type_idx ON app.market_records(record_month,property_type_id); CREATE INDEX market_records_public_idx ON app.market_records(is_public,record_month); CREATE INDEX transactions_month_idx ON app.transactions(transaction_month); CREATE INDEX listings_status_idx ON app.listings(status,published_at); CREATE INDEX listing_price_history_idx ON app.listing_price_history(listing_id,changed_at); CREATE INDEX price_indices_period_type_idx ON app.price_indices(period,property_type_id); CREATE INDEX audit_logs_entity_idx ON app.audit_logs(entity_type,entity_id); CREATE INDEX audit_logs_time_idx ON app.audit_logs(created_at);
REVOKE ALL ON SCHEMA app FROM PUBLIC;
